class PsTabGroupOp extends HTMLElement{constructor(){super(),this.attachShadow({mode:"open"})}connectedCallback(){this.render(),this.setupTabs();const n=Array.from(this.children).findIndex((n=>n.hasAttribute("ativa")));n>=0?this.activateTab(n):this.activateTab(0)}render(){let n="";Array.from(this.children).forEach(((t,e)=>{n+=`\n     <div class="tab-button" data-index="${e}"> ${t.getAttribute("title")||`Tab ${e+1}`} </div>`})),this.shadowRoot.innerHTML=`\n       \n     <style>\n       :host {\n         display: block;\n         font-family: Arial, sans-serif;\n       }\n\n       .contTabs{\n         border: 1px  solid #d1d1d1;  \n         background-color: #f0f0f0;\n         position: relative;\n       }\n       .tab-buttons {\n         display: flex;\n       }\n\n       .tab-button {\n         background-color: #e0e0e0;\n         padding: 10px 15px;\n         cursor: pointer;\n         height: 23px;\n         display: flex;\n         justify-content: center;\n         align-items: center;\n         font-size: 1.1em;\n         color: var(--uxp-host-text-color);\n         box-shadow: 1px 0px 0px 0px #ffffff;\n         margin-right: 1px\n       }\n       .tab-button:hover { \n         color: #000000;\n       }\n       .tab-button.active {\n         background: linear-gradient(90deg, rgba(240,240,240,1) 89%, rgba(240,240,240,1) 96%, rgba(168,168,168,1) 100%);\n       }\n       .tab-content {\n         padding: 10px;\n         border-top: none;\n         display: flex;\n         justify-content: center;\n         align-items: center;\n         margin-top: 23px;\n       }\n\n       .divider{\n           border-right: 1px solid #b4b5b7;  \n           border-left: 1px solid #b4b5b7;  \n       }\n\n       .bgBtns{\n         background-color: #e0e0e0; width: 100%; height: 23px; position: absolute; top: 0px\n       }\n\n       /* Dark mode */\n       @media (prefers-color-scheme: dark), (prefers-color-scheme: darkest) {\n             .contTabs{\n               border: 1px  solid #3a3a3a;  \n               box-shadow: var(--psfx-box-shadow);\n               background-color: #535353;\n               position: relative;\n             }\n             .tab-buttons {\n               display: flex;\n               z-index: 100;\n             }\n             .tab-button {\n               background-color: #424242;\n               padding: 10px 15px;\n               cursor: pointer;\n               height: 23px;\n               display: flex;\n               justify-content: center;\n               align-items: center;\n               font-size: 1.1em;\n               color: var(--uxp-host-text-color);\n               box-shadow: 1px 0px 0px 0px #303030;\n               margin-right: 1px\n             }\n             .tab-button:hover { \n               color: #d5d2d2;\n             }\n\n              .tab-button:active { \n                height: 22px;\n               transform: translate(0px, 1px);\n               border-top: 1px solid #242424;\n               background-color: #747070;\n              }\n\n             .tab-button.active {\n               background: linear-gradient(90deg, rgba(83,83,83,1) 91%, rgba(119,119,119,1) 96%, rgba(41,40,40,1) 100%);\n               pointer-events: none;\n             }\n             .tab-content {\n               padding: 10px;\n               border-top: none;\n               display: flex;\n               justify-content: center;\n               align-items: center;\n               margin-top: 23px;\n             }\n\n             .bgBtns{\n               background-color: #424242; width: 100%; height: 23px; position: absolute; top: 0px\n             }\n         }\n\n     </style>\n   \n       <div class="contTabs">\n         \n         <div class="bgBtns">\n           <div class="tab-buttons">${n}</div>\n         </div>\n         <div class="tab-content"></div>\n         \n     \n     \n     </div>\n     `}setupTabs(){this.shadowRoot.querySelectorAll(".tab-button").forEach(((n,t)=>{n.addEventListener("click",(()=>{this.activateTab(t)}))}))}activateTab(n){const t=this.shadowRoot.querySelectorAll(".tab-button"),e=Array.from(this.children),o=this.shadowRoot.querySelector(".tab-content");if(n>=0&&n<e.length){t.forEach((n=>n.classList.remove("active"))),t[n].classList.add("active"),o.innerHTML="";const a=e[n].cloneNode(!0);o.appendChild(a)}}}customElements.define("ps-tabgroup",PsTabGroupOp);class PsTab extends HTMLElement{constructor(){super()}}customElements.define("ps-tab",PsTab);